/**
 * Starter file byte-sets that real Starter versions shipped and that the
 * upgrade did not recognise until the T1 inventory (2026-10-29), so an
 * untouched copy on any of them stayed `changed` and was never upgraded.
 *
 * Each `content` is the exact file a new Theme received at `sourceCommit`,
 * generated by executing that commit's `src/lib/storefront/starter-theme-files.ts`
 * and reading `STARTER_THEME_FILES` (never hand-typed). `sha256` is the hash of
 * those bytes; `starter-theme-legacy-byte-sets.test.ts` recomputes it, so a
 * change to any byte here fails that test. Matching stays byte-exact: a file is
 * upgraded only when it equals one of these strings.
 */

export type LegacyStarterThemeByteSet = {
  readonly path: string;
  /** Full SHA of the commit whose Starter module produced `content`. */
  readonly sourceCommit: string;
  /** sha256 (hex) of `content` as UTF-8. */
  readonly sha256: string;
  /** Starter versions with at least one commit that shipped these bytes. */
  readonly shippedInVersions: readonly number[];
  readonly content: string;
};

