/** Every byte-set in this module, for the integrity test and the upgrade rules. */
export const LEGACY_STARTER_THEME_SHIPPED_BYTE_SETS: readonly LegacyStarterThemeByteSet[] =
  [
    LEGACY_STARTER_THEME_HERO_DATA_MORPH_ATTRS_BYTE_SET,
    LEGACY_STARTER_THEME_HERO_TARGETLESS_BYTE_SET,
    LEGACY_STARTER_THEME_CATEGORY_SHOWCASE_DATA_MORPH_ATTRS_BYTE_SET,
    LEGACY_STARTER_THEME_CATEGORY_SHOWCASE_PATH_MARKED_SHIPPED_BYTE_SET,
    LEGACY_STARTER_THEME_CATEGORY_SHOWCASE_IMAGE_PATH_MARKED_BYTE_SET,
    LEGACY_STARTER_THEME_CATEGORY_SHOWCASE_IMAGE_MARKED_BYTE_SET,
    LEGACY_STARTER_THEME_IMAGE_WITH_TEXT_DATA_MORPH_ATTRS_BYTE_SET,
    LEGACY_STARTER_THEME_IMAGE_WITH_TEXT_TARGETLESS_BYTE_SET,
    LEGACY_STARTER_THEME_EDITORIAL_INTRO_DATA_MORPH_ATTRS_BYTE_SET,
    LEGACY_STARTER_THEME_NEWSLETTER_DATA_MORPH_ATTRS_BYTE_SET,
    LEGACY_STARTER_THEME_PRINCIPLES_DATA_MORPH_ATTRS_BYTE_SET,
    LEGACY_STARTER_THEME_HEADER_NAV_FIELDS_UNMARKED_BYTE_SET,
    LEGACY_STARTER_THEME_HEADER_UNINDEXED_SHIPPED_BYTE_SET,
    LEGACY_STARTER_THEME_HEADER_INDEXED_SPAN_SHIPPED_BYTE_SET,
    LEGACY_STARTER_THEME_HEADER_INDEX_KEYED_SHIPPED_BYTE_SET,
    LEGACY_STARTER_THEME_FOOTER_NAV_FIELDS_UNMARKED_BYTE_SET,
    LEGACY_STARTER_THEME_FOOTER_INDEX_KEYED_SHIPPED_BYTE_SET,
    LEGACY_STARTER_THEME_HOME_ROUTE_DATA_MORPH_ATTRS_BYTE_SET,
  ];

/** The added byte-sets recognised at `path`, as the strings the rules compare. */
export function legacyStarterThemeShippedSources(path: string): string[] {
  return LEGACY_STARTER_THEME_SHIPPED_BYTE_SETS.filter(
    (set) => set.path === path,
  ).map((set) => set.content);
}
